args<-commandArgs(TRUE);A<-normalizePath(args[1],winslash='/');L<-file.path(A,'plotting');setwd(L);suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(vegan);library(grid)});source('../work/plot_config.R')
read_tsv<-function(p)read.delim(p,quote='"',check.names=FALSE,stringsAsFactors=FALSE,na.strings=c('','NA'))
C<-file.path(A,'02_CONTROLLI');meta<-read_tsv(file.path(C,'Table_S2_Literature_matrix/Record_metadata.tsv'));b<-read_tsv(file.path(C,'Table_S2_Literature_matrix/Binary_matrix.tsv'));mat<-as.matrix(b[-1]);rownames(mat)<-b[[1]];stopifnot(identical(meta$code,colnames(mat)));inventory<-read_tsv(file.path(C,'Table_S1_Literature_inventory/Studies.tsv'))
D<-file.path(C,'FIGURE1_REPRODUCTION');dir.create(D,showWarnings=FALSE);write_tsv<-function(x,n)write.table(x,file.path(D,n),sep='\t',row.names=FALSE,quote=TRUE)
O<-file.path(A,'03_RETTIFICHE_PRONTE/03_MANOSCRITTO');save_figure<-function(p,name,w,h,...){cairo_pdf(file.path(O,paste0(name,'.pdf')),width=w/25.4,height=h/25.4,family='Arial',bg='white');print(p);dev.off();svg(file.path(O,paste0(name,'.svg')),width=w/25.4,height=h/25.4,family='Arial',bg='white');print(p);dev.off()}
source('07_figure1.R');country<-read_tsv(file.path(D,'Figure1_country_counts.tsv'));stopifnot(sum(country$total)==279,country$total[country$country=='India']==10,country$total[country$country=='Turkey']==8)
old<-read_tsv(file.path(C,'Table_S2_Literature_matrix/PCoA.tsv'));new<-read_tsv(file.path(D,'review_PCoA_technique.tsv'));new<-new[match(old$code,new$code),];for(k in c('PC1','PC2')){e<-min(max(abs(old[[k]]-new[[k]])),max(abs(old[[k]]+new[[k]])));stopifnot(e<1e-8)}
cat('FIGURE1_RECONSTRUCTION_PASS:singlecountry279; joint3; India10; annualcounts andPCoA unchanged\n');graphics.off();quit(save='no',status=0,runLast=FALSE)
